import numpy as np
import pandas as pd
from dateutil.easter import easter

# %% ../nbs/01_Foundations/03_Feature_Engineering.ipynb #985386e9
T0 = pd.Timestamp("2006-12-16 17:00")  # first hour of the household data; the phase origin of the Fourier terms


def french_holidays(years) -> pd.DatetimeIndex:
    "French public holidays: eight fixed dates plus Easter Monday, Ascension and Whit Monday."
    days = []
    for yr in years:
        e = pd.Timestamp(easter(yr))
        days += [pd.Timestamp(f"{yr}-{md}") for md in ("01-01", "05-01", "05-08", "07-14", "08-15", "11-01", "11-11", "12-25")]
        days += [e + pd.Timedelta(days=k) for k in (1, 39, 50)]
    return pd.DatetimeIndex(days)


HOLIDAYS = french_holidays(range(2006, 2011))


def make_features(s: pd.Series, groups: tuple = ("calendar", "fourier", "rolling"), exog: pd.DataFrame | None = None) -> pd.DataFrame:
    "Feature table for `s`: seasonal lags (24 to 336 h) plus the named groups; every feature is known 24 h ahead."
    X = pd.DataFrame({f"lag{l}": s.shift(l) for l in (24, 48, 168, 336)}, index=s.index)
    if "calendar" in groups:
        X["hour"], X["dow"], X["month"] = s.index.hour, s.index.dayofweek, s.index.month
        X["holiday"] = s.index.normalize().isin(HOLIDAYS).astype(int)
    if "fourier" in groups:
        t = (s.index - T0) / pd.Timedelta("1h")
        for period, k_max in ((24, 3), (168, 2), (8766, 2)):
            for k in range(1, k_max + 1):
                X[f"sin{period}_{k}"] = np.sin(2 * np.pi * k * t / period)
                X[f"cos{period}_{k}"] = np.cos(2 * np.pi * k * t / period)
    if "rolling" in groups:
        past = s.shift(24)
        X["mean_24h"], X["std_24h"], X["mean_168h"] = past.rolling(24).mean(), past.rolling(24).std(), past.rolling(168).mean()
        X["same_hour_4w"] = pd.concat([s.shift(168 * k) for k in (1, 2, 3, 4)], axis=1).mean(axis=1)
    if "submeters" in groups:
        for c in ("sub1_kwh", "sub2_kwh", "sub3_kwh", "voltage"):
            X[f"{c}_lag24"] = exog[c].reindex(s.index).shift(24)
    return X
